import django.db.models.deletion
import uuid


def number_existing_invoices(apps, schema_editor):
    """Give each existing invoice its own share token, an owner and a sequential number
    (INV/<financial year>/<n>) in creation order, like new invoices get."""
    Invoice = apps.get_model('billing', 'Invoice')
    counters = {}
    for inv in Invoice.objects.select_related('website').order_by('created_at', 'id'):
        inv.public_token = uuid.uuid4()
        inv.owner_id = inv.website.user_id
        day = (inv.created_at or inv.updated_at).date()
        start = day.year if day.month >= 4 else day.year - 1
        fy = f"{start}-{str(start + 1)[2:]}"
        key = (inv.owner_id, fy)
        counters[key] = counters.get(key, 0) + 1
        inv.financial_year, inv.sequence = fy, counters[key]
        inv.invoice_number = f"INV/{fy}/{counters[key]:04d}"
        inv.issue_date = day
        inv.save(update_fields=['public_token', 'owner', 'financial_year', 'sequence', 'invoice_number', 'issue_date'])



